"""Build self-contained Italian illustrated manuals from the verified app catalog.
Run with Python + Pillow, then render PDF with render_manual.cjs over local HTTP.
"""
from pathlib import Path
import argparse, base64, copy, html, io, json, re, os
from PIL import Image

DEFAULT_APP=Path(__file__).resolve().parents[1] if (Path(__file__).resolve().parents[1]/'docs/help_catalog.json').exists() else Path('/workspace/nefrocenter/Presenze_Web_v0.8')
ROOT=Path(os.environ.get('NEFRO_APP_ROOT',str(DEFAULT_APP)))
WORK=Path(os.environ.get('NEFRO_MANUAL_WORK',str(Path(__file__).resolve().parent)))
OUT=Path(os.environ.get('NEFRO_MANUAL_OUT','/workspace/consegna'))
