SETTINGS_LINK=LINK+'/presentation/riferimento-impostazioni.html'
LOGO='data:image/png;base64,'+base64.b64encode((ROOT/'assets/nefrocenter.png').read_bytes()).decode()
E=lambda value:html.escape(str(value),quote=True)

def rich(value):
    return re.sub(r'\*\*(.*?)\*\*',r'<strong>\1</strong>',E(value))

def load_catalog():
    d=json.loads((ROOT/'docs/help_catalog.json').read_text())
    overlay=ROOT/'docs/help_quality.json'
    if overlay.exists():
        q=json.loads(overlay.read_text())
        for key,changes in q.get('topic_updates',{}).items():
            next(t for t in d['topics'] if t['id']==key).update(changes)
        d['quickstarts']=q.get('quickstarts',[])
        for item in q.get('settings',[]):
            existing=next((s for s in d['settings'] if s['id']==item['id'] and s['topic']==item['topic']),None)
            if existing:existing.update(item)
    return d

