MANIFEST={}

def init_manifest():
    global MANIFEST
    p=WORK/'manifest.json'
    if not p.exists():p=ROOT/'assets/guide_screens/manifest.json'
    if p.exists():
        data=json.loads(p.read_text());MANIFEST={**data.get('topics',{}),**data.get('details',{})}

IMAGE_CACHE={}
def picture(topic,require=False,mode='guide'):
    key=(topic,mode)
    if key in IMAGE_CACHE:return IMAGE_CACHE[key]
    selected={'approvazioni':'approval_actions','hrcentrale':'document_review','comunicazioni':'email_preview','uscite':'uscita_detail'}.get(topic,topic)
    item=MANIFEST.get(selected,MANIFEST.get(topic,{}))
    path=Path(item.get('path',WORK/'screenshots'/f'{topic}.png'))
    if not path.is_absolute():path=WORK/path
    if not path.exists():
        bundled=ROOT/'assets/guide_screens'/path.name
        if bundled.exists():path=bundled
    if not path.exists():
        if require:raise FileNotFoundError(path)
        return None
    img=Image.open(path).convert('RGB')
    focus=item.get('focus_pixels')
    crops={'avvio':(1870,825,930,520),'paghe':(470,1030,2670,475),'hrcentrale':(40,585,1040,650),'comunicazioni':(0,855,1309,505),'uscite':(40,575,1040,390)}
    if topic in crops:
        x,y,w,h=crops[topic];focus={'x':x,'y':y,'width':w,'height':h}
    elif img.width>=3000 and focus:
        focus=dict(focus);focus['y']=max(0,focus['y']-70);focus['height']=min(img.height-focus['y'],focus['height']+70)
    if not focus and item.get('focus'):
        f=item['focus'];scale=item.get('viewport',{}).get('deviceScaleFactor',2)
        focus={k:round(f[k]*scale) for k in ('x','y','width','height')}
    if focus and mode!='full':
        x,y,w,h=[int(focus[k]) for k in ('x','y','width','height')]
        x=max(0,x);y=max(0,y);w=min(w,img.width-x);h=min(h,img.height-y)
        if w>0 and h>0:img=img.crop((x,y,x+w,y+h))
    img.thumbnail((1800,1500),Image.Resampling.LANCZOS)
    stream=io.BytesIO();img.save(stream,'JPEG',quality=91,optimize=True,subsampling=0)
    uri='data:image/jpeg;base64,'+base64.b64encode(stream.getvalue()).decode()
    IMAGE_CACHE[key]=uri
    return uri

CAPTIONS={'avvio':'Schermata di accesso del software in un ambiente di prova. Il portale aziendale richiede il proprio account e il secondo fattore.','sicurezza':'La schermata dimostrativa illustra l’area Sicurezza. Autenticazione e recupero reali appartengono all’installazione aziendale.','utenti':'Account e permessi sono illustrati nella demo. La creazione di accessi reali richiede l’installazione aziendale.','esportazioni':'Area di esportazione e backup. La demo non si collega al NAS e non contiene archivi aziendali.'}
def figure(topic,caption=None,require=False,mode='guide'):
    image=picture(topic,require,mode)
    if image is None:return f'<figure class="figure missing">Schermata in preparazione: {E(topic)}</figure>'
    caption=caption or CAPTIONS.get(topic,'Schermata dimostrativa con dati fittizi. I comandi visibili dipendono dal ruolo e dallo stato dei dati.')
    return f'<figure class="figure"><div class="screen-frame"><img src="{image}" alt="Schermata: {E(topic)}"></div><figcaption>{E(caption)}</figcaption></figure>'

def top(label='GUIDA OPERATIVA'):
    return f'<div class="topline"><img src="{LOGO}" alt="NefroCenter"><span>{E(label)} · 0.11</span></div>'

def wrap(title,content,doc='manual'):
    return f'''<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><style>{CSS}</style></head><body><nav class="on-screen"><b>{E(title)}</b><div><a href="#indice">Indice</a><a href="{LINK}">Apri la demo</a><a href="javascript:window.print()">Stampa / PDF</a></div></nav><main data-document="{doc}">{content}</main></body></html>'''

def manual(c,require=False):
    by={t['id']:t for t in c['topics']};order=[key for _,keys in GROUPS for key in keys]
    assert set(order)==set(by) and len(order)==len(by),'Topic map must cover all pages exactly once'
    nums={key:i+1 for i,key in enumerate(order)}
    pieces=[f'''<section class="page cover" id="copertina"><img class="cover-logo" src="{LOGO}" alt="NefroCenter"><div class="eyebrow">Persone e presenze · Manuale illustrato</div><h1>Usare il portale,<br>un passaggio alla volta.</h1><p class="lead">Dalla prima registrazione alla verifica HR: istruzioni pratiche, schermate reali e controlli per capire se il lavoro è concluso.</p><p class="edition">Versione 0.11 · Edizione illustrata</p><div class="cover-art"><div><b>34</b><span>schede operative per pagina e attività</span></div><div><b>323</b><span>impostazioni spiegate nel riferimento consultabile</span></div><div><b>5</b><span>ruoli, con compiti e limiti distinti</span></div><div><b>1</b><span>archivio centrale nell’installazione aziendale</span></div></div><p class="cover-foot">Per responsabili, HR, compilatori, amministratori e lettori.<br>Le immagini utilizzano esclusivamente dati dimostrativi.</p></section>''']
    pieces.append(f'''<section class="page" id="come-leggere">{top()}<div class="eyebrow">Inizia da qui</div><h2>Una guida da usare<br>mentre lavori.</h2><p class="intro">Non occorre leggerla tutta in ordine. Cerca il tuo compito nell’indice, apri la scheda e segui i passaggi nella pagina del software.</p><div class="summary-grid"><div class="card"><div class="eyebrow">01 · Prima</div><h3>Controlla il contesto</h3><p>Ogni scheda indica a chi è rivolta e cosa serve prima di cominciare. Verifica sempre struttura, persona e mese.</p></div><div class="card"><div class="eyebrow">02 · Durante</div><h3>Segui i comandi</h3><p>I nomi citati corrispondono a pulsanti e campi del portale. La schermata ti aiuta a riconoscere la pagina.</p></div><div class="card"><div class="eyebrow">03 · Dopo</div><h3>Verifica il risultato</h3><p>Il riquadro verde indica cosa controllare dopo il salvataggio. Un messaggio di errore richiede una correzione, non un invio ripetuto.</p></div><div class="card"><div class="eyebrow">04 · Se serve</div><h3>Risolvi il blocco</h3><p>Il riquadro giallo raccoglie i casi frequenti. Per una singola impostazione usa il riferimento ricercabile.</p></div></div><div class="callout"><h3>Demo e portale aziendale</h3><p style="margin-top:10px">La <a href="{LINK}">demo pubblica</a> usa dati fittizi e una copia separata per ogni visitatore. Il portale operativo usa account nominativi e un archivio condiviso sul server aziendale. Le email nella demo sono sempre simulate.</p></div><h3>Quando un comando non compare</h3><p style="margin-top:10px">Controlla il ruolo, i centri assegnati e lo stato del dato. Un mese inviato, un percorso concluso o un’operazione riservata possono bloccare una modifica. L’assenza di un pulsante non si risolve cambiando i dati alla cieca.</p><div class="settings-link"><h3>Il dettaglio dei campi resta a portata di mano</h3><p>Nel portale apri <b>Guide e tutorial → Riferimento impostazioni</b>. La versione HTML autonoma <a href="{SETTINGS_LINK}"><b>Riferimento_Impostazioni_NefroCenter_v0.11.html</b></a> permette di cercare fra tutte le 323 voci.</p></div></section>''')
    for part in [QUICKSTARTS[:3],QUICKSTARTS[3:]]:
        cards=''.join(f'''<article class="card"><div class="eyebrow">{E(role)}</div><h3>{E(title)}</h3><p>{E(desc)}</p><p class="role-path">{' → '.join(f'<a href="#{key}">{nums[key]:02d} · {E(by[key]["title"])}</a>' for key in topics)}</p></article>''' for role,title,desc,topics in part)
        extra='''<div class="callout"><h3>Un permesso vale nel suo perimetro</h3><p style="margin-top:9px">HR centrale opera sulle strutture del gruppo. Responsabili, compilatori e lettori vedono i centri assegnati. La possibilità di aprire una pagina non implica che tutte le sue azioni siano consentite.</p></div>''' if len(part)==2 else ''
        pieces.append(f'<section class="page">{top()}<div class="eyebrow">Percorsi consigliati</div><h2>Parti dal tuo ruolo.</h2><p class="intro">Una sequenza breve per le attività più comuni. I numeri rimandano alle schede del manuale.</p><div class="role-list">{cards}</div>{extra}</section>')
    pieces.append(f'''<section class="page" id="workflow">{top()}<div class="eyebrow">Il lavoro fra sede e HR</div><h2>Una presenza, tre verifiche.</h2><p class="intro">Quando l’amministratore attiva il percorso di approvazione per una struttura, il mese segue questi passaggi.</p><div class="workflow"><div><b class="step">1</b><section><h3>La sede compila e invia</h3><p>Il compilatore registra il consuntivo, risolve i dati mancanti e invia il mese. Dopo l’invio le modifiche al registro sono bloccate.</p></section></div><div><b class="step">2</b><section><h3>Il responsabile verifica</h3><p>Controlla registrazioni e calendario. Inoltra a HR oppure restituisce alla sede con una motivazione.</p></section></div><div><b class="step">3</b><section><h3>HR approva la chiusura</h3><p>HR centrale o l’amministratore approva la versione verificata. I controlli bloccanti devono essere risolti; una modifica dei riferimenti richiede una nuova verifica.</p></section></div></div><div class="callout"><h3>Se qualcosa cambia, si torna al passaggio corretto</h3><p style="margin-top:9px">La restituzione motivata riapre la compilazione. Per correggere un mese chiuso serve la riapertura autorizzata. Lo storico conserva autore, data e passaggio.</p></div><p class="small">Senza il percorso attivo resta la chiusura ordinaria prevista dai ruoli. I mesi chiusi prima dell’attivazione non ricevono un’approvazione HR retroattiva.</p><div class="summary-grid" style="margin-top:25px"><div class="card"><h3>Documenti</h3><p style="margin-top:9px">La sede carica. HR verifica o richiede correzioni. La sede richiede una nuova verifica; lo stato di scadenza rimane distinto.</p><a href="#documenti">Schede {nums['documenti']:02d}–{nums['hrcentrale']:02d} →</a></div><div class="card"><h3>Uscite e dotazioni</h3><p style="margin-top:9px">Il referente completa le attività e registra le restituzioni. La conclusione del percorso non modifica da sola anagrafiche e account esterni.</p><a href="#uscite">Scheda {nums['uscite']:02d} →</a></div></div></section>''')
    for n,groups in enumerate([GROUPS[:3],GROUPS[3:]]):
        blocks=''.join('<div class="toc-group"><h3>'+E(name)+'</h3>'+''.join(f'<a class="toc-row" href="#{key}"><span class="number">{nums[key]:02d}</span><span>{E(by[key]["title"])}</span></a>' for key in keys)+'</div>' for name,keys in groups)
        pieces.append(f'<section class="page" id="{"indice" if n==0 else "indice-2"}">{top()}<div class="eyebrow">Trova la scheda</div><h2>Indice operativo{ " · continua" if n else ""}.</h2><p class="intro">Clicca il titolo per raggiungere la procedura.</p>{blocks}</section>')
    for key in order:
        t=by[key];before=t.get('before',[])
        if isinstance(before,str):before=[before]
        steps=t['steps'];errors=t.get('errors',[])[:3]
        textcount=sum(len(str(x)) for x in steps+errors)+len(t.get('goal',''))+len(t.get('result',''))
        long=' topic-long' if textcount>1750 or len(steps)>6 else ''
        setting_count=sum(s['topic']==key for s in c['settings'])
        example=t.get('example','')
        if isinstance(example,dict):example=' · '.join(str(v) for v in example.values())
        if isinstance(example,list):example=' '.join(example)
        before_html=f'<div class="before"><b>Prima di iniziare</b> · {" ".join(E(x) for x in before)}</div>' if before else ''
        example_html=('<div class="example"><b>Esempio</b> · '+rich(example)+'</div>') if example else ''
        error_html='<ul>'+''.join('<li>'+rich(x)+'</li>' for x in errors)+'</ul>' if errors else 'Se il salvataggio non riesce, leggi l’avviso e verifica i dati richiesti prima di riprovare.'
        pieces.append(f'''<section class="page topic{long}" id="{key}" data-topic="{key}">{top()}<div class="topic-heading"><div><div class="eyebrow">Scheda operativa</div><h2>{E(t['title'])}</h2></div><span class="sheet-number">{nums[key]:02d}</span></div><p class="goal">{E(t['goal'])}</p><p class="who"><b>A chi serve</b> · {E(t['audience'])}{(' · '+E(t['duration'])) if t.get('duration') else ''}</p>{before_html}{figure(key,require=require)}<h3 class="section-label">Cosa fare</h3><ol class="steps">{''.join('<li><span>'+rich(step)+'</span></li>' for step in steps)}</ol><div class="bottom-grid"><div class="result"><h4>Controlla il risultato</h4>{rich(t['result'])}{example_html}</div><div class="help"><h4>Se qualcosa non torna</h4>{error_html}</div></div><p class="topic-foot">{str(setting_count)+' impostazioni spiegate nel <a href="'+SETTINGS_LINK+'">riferimento ricercabile</a>. · ' if setting_count else ''}<a href="#indice">Torna all’indice</a> · Aiuto contestuale disponibile anche nel portale.</p></section>''')
    pieces.append(f'''<section class="page" id="fine">{top()}<div class="eyebrow">Prima del lavoro reale</div><h2>Avvia una sede pilota.</h2><p class="intro">Questa guida descrive il programma. Il passaggio all’uso aziendale richiede dati, responsabilità e servizi concordati.</p><ul class="checklist"><li>Account nominativi, ruolo e strutture assegnate verificati.</li><li>Fasce, causali, calendario e accordi controllati con il referente.</li><li>Un fascicolo e un documento caricati dalla sede e consultati da HR.</li><li>Un mese di prova compilato, verificato e chiuso con il percorso scelto.</li><li>Un file paghe verificato dal consulente sul tracciato concordato.</li><li>Posta, mittente e destinatari verificati prima di abilitare gli invii.</li><li>Seconda copia NAS e ripristino provati con il tecnico.</li></ul><div class="settings-link"><h3>Continua dal portale</h3><p><b>Aiuto per questa pagina</b> apre la procedura del punto in cui ti trovi. <b>Guide e tutorial</b> raccoglie video, procedure e impostazioni.</p><p><a href="{LINK}">{LINK}</a></p></div><p class="small muted" style="margin-top:30px">Manuale del software NefroCenter · versione 0.11. Screenshot dimostrativi, senza dati reali. Per l’installazione leggi INSTALLAZIONE_IN_BREVE.md; per gli esiti di collaudo consulta VERIFICA.md.</p></section>''')
    return wrap('NefroCenter · Guida illustrata', ''.join(pieces))

SETTINGS_CSS='''body{background:#f0f5f8;font:16px/1.5 Arial,sans-serif;color:#19374e;margin:0}.shell{max-width:1160px;margin:auto;padding:32px 24px}header{padding:32px 0}header img{width:200px}h1{font-size:42px;line-height:1.1;margin:25px 0 15px}header p{max-width:760px;color:#536d7e}a{color:#146f7c}button,input,select{font:inherit;border:1px solid #b9ced9;border-radius:8px;background:white;padding:12px;color:#19374e}button{cursor:pointer}label{display:block;font-weight:700;font-size:13px;margin-bottom:6px}.filters{display:grid;grid-template-columns:2fr 1fr;gap:15px;position:sticky;top:0;background:#f0f5f8;padding:18px 0;z-index:2}.filters input,.filters select{width:100%}.count{color:#506a7b;margin:8px 0 20px}.list{display:grid;grid-template-columns:1fr 1fr;gap:16px}.setting{border:1px solid #cfdee6;padding:23px;background:white;border-radius:12px}.setting h2{font-size:20px;margin:7px 0 13px}.setting .topic{font-size:12px;font-weight:bold;letter-spacing:.7px;text-transform:uppercase;color:#16877f}.setting .effect{margin:0 0 15px}.setting .example{background:#edf5f6;border-left:3px solid #248c84;padding:12px;font-size:14px}.setting code{font-size:12px;color:#637988}.footer{border-top:1px solid #cfdee6;margin:30px 0;padding-top:20px;color:#5b7587}.empty{padding:40px;text-align:center;background:white;border-radius:10px}@media(max-width:650px){h1{font-size:32px}.filters,.list{grid-template-columns:1fr}.shell{padding:20px 16px}.filters{position:static}}@media print{body{background:white;font-size:10pt}.filters,.no-print{display:none}.shell{max-width:none;padding:0}.list{display:block}.setting{break-inside:avoid;margin:0 0 10px;padding:14px}.setting h2{font-size:13pt}.setting .example{font-size:9pt}header{padding:0}h1{font-size:25pt}@page{size:A4;margin:18mm}}
'''
def settings_html(c):
    data=json.dumps({'topics':[{'id':t['id'],'title':t['title']} for t in c['topics']],'settings':c['settings']},ensure_ascii=False).replace('</',r'<\/')
    return f'''<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NefroCenter · Riferimento impostazioni</title><style>{SETTINGS_CSS}</style></head><body><main class="shell"><header><img src="{LOGO}" alt="NefroCenter"><p>GUIDA OPERATIVA · VERSIONE 0.11</p><h1>Trova il significato<br>di ogni impostazione.</h1><p>Cerca un nome, un esempio o un effetto. Ogni voce spiega cosa cambia e dove si trova. Questo documento si consulta anche senza connessione; i permessi effettivi restano quelli del portale.</p><p class="no-print"><a href="{LINK}">Apri la demo</a> · <button onclick="window.print()">Stampa i risultati</button></p></header><form class="filters" onsubmit="event.preventDefault()"><div><label for="search">Cerca nei 323 riferimenti</label><input id="search" type="search" placeholder="Per esempio: pausa, NAS, verifica, email HR" autocomplete="off"></div><div><label for="topic">Pagina o attività</label><select id="topic"><option value="">Tutte le pagine</option></select></div></form><div class="count" id="count" role="status" aria-live="polite"></div><div class="list" id="list"></div><footer class="footer">323 riferimenti alle impostazioni · NefroCenter 0.11. I campi riservati sono visibili soltanto agli utenti autorizzati. Gli esempi sono fittizi.</footer></main><script>const data={data};const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));const fold=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const topics=Object.fromEntries(data.topics.map(t=>[t.id,t.title]));const select=document.querySelector('#topic');for(const t of data.topics)if(data.settings.some(s=>s.topic===t.id))select.insertAdjacentHTML('beforeend','<option value="'+esc(t.id)+'">'+esc(t.title)+'</option>');function draw(){{const q=fold(document.querySelector('#search').value.trim()),key=select.value;const rows=data.settings.filter(s=>(!key||s.topic===key)&&(!q||fold([s.id,s.label,s.section,s.effect,s.example,topics[s.topic]].join(' ')).includes(q)));document.querySelector('#count').textContent=rows.length+' di '+data.settings.length+' impostazioni';document.querySelector('#list').innerHTML=rows.length?rows.map(s=>'<article class="setting"><div class="topic">'+esc(topics[s.topic])+' · '+esc(s.section)+'</div><h2>'+esc(s.label)+'</h2><p class="effect">'+esc(s.effect)+'</p><p class="example"><b>Esempio</b><br>'+esc(s.example)+'</p><code>'+esc(s.id)+'</code></article>').join(''):'<p class="empty">Nessuna impostazione trovata. Prova una parola più breve oppure scegli tutte le pagine.</p>'}}document.querySelector('#search').addEventListener('input',draw);select.addEventListener('change',draw);draw();</script></body></html>'''

# Editorial HR companion: concise, screen-supported and aligned with actual functions.
def hr_presentation(require=False):
    def page(label,title,body,id=''):
        return f'<section class="page hr-page" id="{id}">{top("PRESENTAZIONE PER HR")}<div class="eyebrow">{label}</div><h2>{title}</h2>{body}</section>'
    def p(value):return '<p>'+value+'</p>'
    a=[]
    a.append(f'''<section class="page cover" id="hr-cover"><img class="cover-logo" src="{LOGO}" alt="NefroCenter"><div class="eyebrow">Persone e presenze · Presentazione per HR</div><h1>Le strutture e HR,<br>nello stesso portale.</h1><p class="lead">Persone, presenze, documenti e attività amministrative: una vista condivisa, con responsabilità e accessi distinti.</p><p class="edition">Versione 0.11 · Guida alla riunione</p><div class="cover-art"><div><b>Persone</b><span>fascicoli, documenti, onboarding e uscite</span></div><div><b>Presenze</b><span>registro, approvazioni e copertura turni</span></div><div><b>HR</b><span>controlli centrali e comunicazioni</span></div><div><b>Guide</b><span>procedure e tutorial per ogni pagina</span></div></div><p class="cover-foot">Schermate e dati dimostrativi.<br>Per presentare il software e concordare una sede pilota.</p></section>''')
    a.append(page('01 · Il punto di partenza','Un archivio centrale.<br>Compiti riconoscibili.',f'''<p class="intro">Il portale operativo si installa una volta sul server aziendale. Sedi e ufficio HR lo aprono dal browser e lavorano sugli stessi dati, nei limiti del proprio ruolo.</p>{figure('dashboard',require=require)}<div class="two"><div><h3>Per le sedi</h3><p>Registrare il lavoro svolto, mantenere i fascicoli assegnati, caricare documenti e seguire le attività.</p></div><div><h3>Per HR centrale</h3><p>Consultare i documenti delle strutture, verificare informazioni, approvare i mesi e coordinare scadenze e comunicazioni.</p></div></div><div class="callout"><b>Messaggio da presentare</b><p style="margin-top:9px">«Le informazioni non devono essere ricopiate fra archivi separati: sede e HR consultano lo stesso dato, con passaggi e controlli visibili.»</p></div>''','indice'))
    a.append(page('02 · Un esempio concreto','Dalla sede al controllo HR.',f'''<p class="intro">Una nuova persona entra in una struttura. Il responsabile apre il fascicolo, completa i dati, segue l’onboarding e allega il contratto.</p>{figure('hrcentrale',require=require)}<div class="flow-row"><div><b>1. Carica</b>La sede autorizzata allega PDF o immagini nel fascicolo.</div><div><b>2. Consulta</b>HR trova lo stesso file nell’archivio Documenti HR.</div><div><b>3. Verifica</b>HR conferma oppure richiede una correzione motivata.</div><div><b>4. Ripresenta</b>La sede corregge e richiede una nuova verifica.</div></div><p>Il documento conserva autore, data e impronta di integrità; lo storico mostra i passaggi. La scadenza rimane distinta dalla verifica HR.</p><p class="small muted">Formati ammessi: PDF, PNG e JPEG fino a 6 MiB. Non è incluso un portale personale autonomo del dipendente: il caricamento compete agli utenti HR autorizzati.</p>'''))
    a.append(page('03 · Presenze e approvazioni','Un mese chiuso<br>dopo le verifiche.',f'''<p class="intro">Il registro distingue pianificato e consuntivo, orari, pause, causali, sede effettiva e festivi. I dati mancanti rimangono segnalati.</p>{figure('approvazioni',require=require)}<div class="flow-row"><div><b>Sede</b>Compila e invia il mese. Dopo l’invio il registro è bloccato.</div><div><b>Responsabile</b>Verifica registrazioni e calendario; inoltra a HR o restituisce.</div><div><b>HR</b>Approva la chiusura quando i controlli sono risolti.</div></div><p>Restituzioni e riaperture richiedono una motivazione. Versioni e impronte impediscono di approvare dati superati; lo storico conserva autore e passaggio.</p><p class="small muted">Il percorso è attivabile per struttura e nasce disattivato nell’installazione. I mesi già chiusi non ricevono una verifica HR retroattiva. Senza il flusso resta la chiusura ordinaria autorizzata.</p>'''))
    a.append(page('04 · Organizzazione dei turni','Vedere le scoperture.<br>Confermare le sostituzioni.',f'''<p class="intro">Il responsabile definisce minimi per giorno, fascia e qualifica, con eccezioni per data. La copertura confronta fabbisogno, pianificato e consuntivo.</p>{figure('copertura',require=require)}<div class="two"><div><h3>Disponibilità</h3><p>HR e responsabili registrano disponibilità, indisponibilità e preferenze. Le note restano riservate; altri ruoli vedono i conteggi aggregati.</p></div><div><h3>Sostituzioni</h3><p>Le proposte usano anagrafiche già collegate alla stessa identità. Il responsabile destinatario decide; l’accettazione ricontrolla periodo e conflitti prima di creare il pianificato.</p></div></div><div class="callout"><p>I minimi sono riferimenti organizzativi concordati dall’azienda: il programma non certifica l’adeguatezza clinica della dotazione.</p></div>'''))
    a.append(page('05 · Persone e processi','Il fascicolo accompagna<br>il rapporto di lavoro.',f'''<p class="intro">Anagrafica, recapiti, rapporto, amministrazione, qualifiche e riferimenti della struttura convivono con attività, allegati e storico.</p>{figure('dipendenti',require=require)}<div class="two"><div><h3>Ingresso e scadenze</h3><p>Checklist configurabile con responsabile, scadenza e stato. Le date salvate alimentano le attività da verificare.</p><h3>Personale di gruppo</h3><p>Collegamenti espliciti fra anagrafiche e decorrenze contrattuali ed economiche, senza fusioni automatiche basate sul nome.</p></div><div><h3>Uscite e dotazioni</h3><p>Percorsi di cessazione o trasferimento, checklist e registro di badge, chiavi e dispositivi. La conclusione richiede attività completate e restituzioni registrate.</p><p class="small muted">Completare il percorso non disattiva da solo account esterni e non trasferisce o cessa automaticamente l’anagrafica.</p></div></div>'''))
    a.append(page('06 · Comunicazioni','Preparare i messaggi.<br>Controllare i destinatari.',f'''<p class="intro">HR e amministratori preparano modelli e liste, leggono l’anteprima personalizzata e conservano una bozza con testi e destinatari verificati.</p>{figure('comunicazioni',require=require)}<div class="two"><div><h3>Invii manuali</h3><p>Un destinatario per email; deduplicazione e conferma del singolo lotto. Lo storico distingue accettazione SMTP, errore ed esito incerto.</p></div><div><h3>Promemoria automatici</h3><p>Riepiloghi di scadenze ai recapiti autorizzati, con conteggi senza nomi o allegati riservati. L’amministratore configura frequenza, limiti e destinatari dopo l’anteprima.</p></div></div><div class="callout"><p>Il fornitore di posta non è ancora scelto. SMTP e promemoria nascono disattivati. Nella demo gli invii sono simulati; “accettato dal server” non significa “ricevuto o letto”.</p></div>'''))
    a.append(page('07 · Risultati e consegne','Preparare dati verificabili<br>per direzione e consulente.',f'''<p class="intro">Le statistiche confrontano ore, turni, assenze registrate e completezza. Gli export rispettano il perimetro del ruolo.</p>{figure('paghe',require=require)}<div class="two"><div><h3>Accordi e calcoli</h3><p>Condizioni individuali per persona, sede e mese, con modelli a turni, ore o quota fissa. Le proposte devono essere controllate e confermate.</p><h3>Prospetti</h3><p>CSV ed Excel per presenze, statistiche, fascicoli, onboarding e accordi. I dati mancanti non vengono stimati come se fossero completi.</p></div><div><h3>Tracciato paghe</h3><p>Intestazioni CSV o specifica JSON, mappatura delle colonne, causali, matricole, date e codifica. L’anteprima blocca le anomalie pertinenti.</p><p class="small muted">Il gestionale del consulente è ancora sconosciuto. Il modello generico è una bozza da concordare; il portale non produce cedolini e non dichiara una compatibilità certificata con un fornitore.</p></div></div>'''))
    roles=[('Amministratore','Tutte le strutture; gestione tecnica e operativa.','Crea account e centri, configura permessi, posta, backup e processi. È il profilo più esteso.'),('HR centrale','Personale e documenti di tutte le sedi.','Verifica documenti, approva i mesi, gestisce fascicoli, decorrenze, comunicazioni e uscite. Non modifica direttamente presenze o parametri e non gestisce SMTP, utenti o backup tecnici.'),('Responsabile centro','Solo le sedi assegnate.','Gestisce presenze, fascicoli, coperture e attività; verifica il mese e lo inoltra a HR. Non effettua l’approvazione finale HR né la verifica documentale riservata.'),('Compilatore','Registro delle sedi assegnate.','Compila secondo i permessi del centro e può inviare il mese. Non accede a fascicoli HR, documenti riservati, accordi o paghe.'),('Direzione / lettore','Consultazione dei centri assegnati.','Consulta dashboard, registro, riepiloghi e statistiche. Non modifica dati e non accede ai fascicoli riservati.')]
    a.append(page('08 · Ruoli e responsabilità','A ciascuno il lavoro<br>di propria competenza.','<p class="intro">Account nominativi e secondo fattore nel portale operativo. I cinque profili della demo servono a provare i diversi punti di vista.</p><div class="role-list">'+''.join(f'<article class="card"><h3>{E(name)}</h3><p class="muted"><b>{E(scope)}</b></p><p>{E(can)}</p></article>' for name,scope,can in roles)+'</div><p class="small muted">Un lettore non riceve automaticamente tutte le sedi. Il ruolo personale “dipendente” con accesso self-service non è incluso.</p>'))
    a.append(page('09 · Scaletta per la riunione','Una demo in dieci minuti.',f'''<p class="intro">Apri <a href="{LINK}">{LINK}</a>. Spiega subito che i dati sono fittizi e che ogni visitatore lavora su una copia separata.</p><div class="workflow"><div><b class="step">0–2</b><section><h3>Presentazione e ruoli</h3><p>Mostra il video e la scelta dei profili. Collega ogni ruolo a una responsabilità reale dell’ufficio.</p></section></div><div><b class="step">2–4</b><section><h3>Dalla sede a HR</h3><p>Apri un fascicolo e un documento dimostrativo. Passa a HR e mostra ricerca centrale, verifica e correzioni.</p></section></div><div><b class="step">4–6</b><section><h3>Presenze e approvazioni</h3><p>Distingui pianificato e consuntivo; mostra i passaggi della verifica mensile e la restituzione motivata.</p></section></div><div><b class="step">6–8</b><section><h3>Organizzazione e comunicazioni</h3><p>Apri Copertura, poi un’anteprima email e i promemoria. Ricorda che nessun messaggio reale parte dalla demo.</p></section></div><div><b class="step">8–10</b><section><h3>Guide e avvio</h3><p>Mostra la guida della pagina. Concludi con sede pilota, ruoli, dati da concordare e servizi da configurare.</p></section></div></div><p class="small muted">Cambia profilo nella stessa scheda per mantenere il campione di lavoro. Un altro visitatore non vede queste modifiche. “Ripristina demo” riporta ai dati iniziali.</p>'''))
    a.append(page('10 · Passare all’uso aziendale','Una sede pilota,<br>con HR e IT insieme.',f'''<p class="intro">Il software operativo richiede server centrale, HTTPS, Python e dipendenze, account nominativi e una gestione tecnica concordata. Alle postazioni basta il browser.</p><div class="two"><div><h3>Decisioni HR</h3><ul><li>Strutture, persone autorizzate e responsabilità.</li><li>Campi, documenti, checklist e conservazione.</li><li>Fasce, causali, calendario e accordi.</li><li>Percorso di approvazione mensile.</li><li>Tracciato concordato col consulente.</li></ul></div><div><h3>Configurazione IT</h3><ul><li>Server, accesso HTTPS e secondo fattore.</li><li>Backup e seconda copia sul NAS.</li><li>Custodia separata della chiave privata.</li><li>Posta, mittente e destinatari autorizzati.</li><li>Prova completa di ripristino e accesso.</li></ul></div></div><div class="callout"><h3>Prima prova condivisa</h3><p style="margin-top:9px">Un mese di presenze, un fascicolo, un documento caricato dalla sede e consultato da HR, un file paghe controllato dal consulente e un ripristino verificato dal tecnico.</p></div><h3>Materiali disponibili</h3><ul><li>Manuale illustrato: 34 schede, schermate e controlli di risultato.</li><li>Riferimento ricercabile: 323 impostazioni.</li><li>Guide contestuali e videoguide nel portale.</li><li>Video di presentazione con voce italiana e versione senza audio.</li><li>INSTALLAZIONE_IN_BREVE.md e risultati di collaudo in VERIFICA.md.</li></ul><p class="small muted">Il gestionale non è ancora installato sul server aziendale. Percorso NAS, servizio di posta e tracciato del consulente restano da definire e collaudare.</p>'''))
    return wrap('NefroCenter · Presentazione per HR',''.join(a),'hr')

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--require-images',action='store_true');args=parser.parse_args()
    WORK.mkdir(exist_ok=True);OUT.mkdir(exist_ok=True);init_manifest();c=load_catalog()
    outputs={'Guida_NefroCenter_v0.11_illustrata.html':manual(c,args.require_images),'Riferimento_Impostazioni_NefroCenter_v0.11.html':settings_html(c),'Presentazione_HR_NefroCenter_v0.11_illustrata.html':hr_presentation(args.require_images)}
    for name,content in outputs.items():(WORK/name).write_text(content);(OUT/name).write_text(content)
    (WORK/'manual-catalog-snapshot.json').write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'outputs':list(outputs),'topics':len(c['topics']),'settings':len(c['settings']),'images':len(IMAGE_CACHE)},ensure_ascii=False))
